-- prep_tip UPDATE statements for all milestone windows
-- Run after: 20260319_prep_tip_column.sql

UPDATE milestone_windows SET prep_tip = 'Iron supplementation for breastfed babies is recommended starting at 4 months. It''s a simple liquid drop — ask about it at the 4-month visit.' WHERE slug = 'nutrition-iron-supplement-breastfed';
UPDATE milestone_windows SET prep_tip = 'Early peanut introduction is now recommended for most babies — it reduces allergy risk significantly. Talk to your pediatrician at the 4-month visit about timing and method before this window opens.' WHERE slug = 'nutrition-peanut-intro';
UPDATE milestone_windows SET prep_tip = 'Egg is a top allergen and should be introduced early. Scrambled egg or hard-boiled egg yolk, mashed fine, works well. Introduce alone first to watch for a reaction.' WHERE slug = 'nutrition-egg-intro';
UPDATE milestone_windows SET prep_tip = 'Thinned nut butter mixed into puree is an easy tree nut introduction. Introduce one nut at a time on a day when you''re home and can observe for a reaction.' WHERE slug = 'nutrition-tree-nut-intro';
UPDATE milestone_windows SET prep_tip = 'Get a firm, flat surface ready for tummy time — a play mat on the floor works perfectly. Starting from day one, even a minute at a time, makes a big difference.' WHERE slug = 'motor-tummy-time-start';
UPDATE milestone_windows SET prep_tip = 'Tummy time will start feeling more productive this month as your baby gets stronger. Build toward 20 minutes total per day — it doesn''t have to be in one session.' WHERE slug = 'motor-tummy-time-build';
UPDATE milestone_windows SET prep_tip = 'Keep up tummy time and begin carrying your baby upright against your shoulder — both build the neck strength for head control.' WHERE slug = 'motor-head-control';
UPDATE milestone_windows SET prep_tip = 'As soon as you see rolling attempts, stop swaddling immediately — arms must be free. If your baby isn''t rolling yet, watch closely and be ready to transition fast.' WHERE slug = 'motor-swaddle-stop';
UPDATE milestone_windows SET prep_tip = 'Clear open floor space and get shoes that are flexible and flat — feet need to feel the ground to develop balance. Stiff soles actually slow the process.' WHERE slug = 'motor-first-steps';
UPDATE milestone_windows SET prep_tip = 'Clear the walking path and get shoes that are flexible and flat — feet need to feel the ground to develop balance. Stiff soled shoes actually slow the walking process.' WHERE slug = 'motor-walking-independent';
UPDATE milestone_windows SET prep_tip = 'When your baby makes sounds, respond to them. That''s it. The habit of back-and-forth is what matters, not what you say.' WHERE slug = 'language-serve-return';
UPDATE milestone_windows SET prep_tip = 'No prep needed — watch for your newborn to startle or calm in response to your voice and sounds. It''s one of the earliest signs that hearing is working.' WHERE slug = 'language-startle-to-sound';
UPDATE milestone_windows SET prep_tip = 'Your baby''s first intentional smile is coming — watch for it after a feed when they''re content and looking at your face. It will stop you cold.' WHERE slug = 'language-social-smile';
UPDATE milestone_windows SET prep_tip = 'Start pointing at things and saying their names. Pointing-and-naming together builds joint attention — the shared focus that is the foundation of language learning.' WHERE slug = 'language-joint-attention-pointing';
UPDATE milestone_windows SET prep_tip = 'Keep using ''mama'' and ''dada'' consistently and specifically — always pointing to the right person. The specific assignment is what they''re working on, not just the sounds.' WHERE slug = 'language-mama-dada-specific';
UPDATE milestone_windows SET prep_tip = 'First words beyond ''mama'' and ''dada'' are coming. Keep naming everything, reading aloud, and responding to all attempts at communication as real words.' WHERE slug = 'language-first-words';
UPDATE milestone_windows SET prep_tip = 'Start keeping a mental note of the words your child uses consistently — not just sounds, but real words used with intent. You''ll want a count for the 18-month visit.' WHERE slug = 'language-vocab-10-words';
UPDATE milestone_windows SET prep_tip = 'Keep reading aloud daily — it''s the single highest-leverage action for vocabulary growth right now. Point to pictures, name them, and wait for your child to name them back.' WHERE slug = 'language-vocab-50-words';
UPDATE milestone_windows SET prep_tip = 'Model two-word phrases naturally in response to your child''s single words: when they say ''ball,'' you say ''throw ball'' or ''big ball.'' The pattern is what they''re absorbing.' WHERE slug = 'language-2-word-combinations';
UPDATE milestone_windows SET prep_tip = 'Keep the conversation going constantly — narrate, question, read aloud. If you have concerns about vocabulary at this stage, now is the time to bring them up.' WHERE slug = 'language-vocab-200-words';
UPDATE milestone_windows SET prep_tip = 'Expand your child''s two-word phrases: when they say ''daddy go,'' you say ''daddy went to work.'' Model without correcting — imitation is how grammar develops.' WHERE slug = 'language-3-word-sentences';
UPDATE milestone_windows SET prep_tip = 'Keep having real conversations — ask open questions, let them finish sentences, don''t rush to fill the gaps. Sentence length grows from being given space to talk.' WHERE slug = 'language-full-sentences';
UPDATE milestone_windows SET prep_tip = 'Get a small collection of board books before your baby arrives. Reading aloud from birth builds the habit and the bond — the content matters less than the routine.' WHERE slug = 'language-read-aloud-daily';
UPDATE milestone_windows SET prep_tip = 'Nothing to buy or prepare — skin-to-skin happens in the first hours after birth. Tell your birth team you want it immediately if your baby is healthy. That''s the whole plan.' WHERE slug = 'social-skin-to-skin';
UPDATE milestone_windows SET prep_tip = 'Tantrums peak between 18 and 30 months. The preparation is mental, not material: decide your response strategy before the next meltdown, not during it.' WHERE slug = 'social-tantrums-peak';
UPDATE milestone_windows SET prep_tip = 'Smile back every time. That back-and-forth is wiring your baby''s social brain and you cannot overdo it.' WHERE slug = 'social-respond-to-smile';
UPDATE milestone_windows SET prep_tip = 'Point to things and name them during your daily routine. Your baby is about to follow where you''re pointing — that shared attention is a vocabulary-building superpower.' WHERE slug = 'social-joint-attention';
UPDATE milestone_windows SET prep_tip = 'Your baby''s social smile is about to emerge — the real one, intentional and directed at you. Watch for it in quiet alert moments when they''re gazing at your face.' WHERE slug = 'social-social-smile-appears';
UPDATE milestone_windows SET prep_tip = 'Postpartum depression affects 1 in 5 mothers and 1 in 10 fathers. Screens are given at 1 and 2 month visits. Know the signs: persistent sadness, disconnection, inability to function.' WHERE slug = 'social-parent-depression-screening';
UPDATE milestone_windows SET prep_tip = 'Safe sleep setup should be ready before you leave the hospital. Firm mattress, no bumpers, no loose items. If you haven''t done it yet, do it today.' WHERE slug = 'safety-safe-sleep-setup';
UPDATE milestone_windows SET prep_tip = 'Back-to-sleep is a reflex to build into your routine from day one. Every person who puts your baby down needs to know: always on their back.' WHERE slug = 'safety-back-to-sleep';
UPDATE milestone_windows SET prep_tip = 'The AAP recommends room sharing (not bed sharing) for the first 6 months. A bassinet or bedside sleeper in your room is the setup to arrange before birth.' WHERE slug = 'safety-room-sharing';
UPDATE milestone_windows SET prep_tip = 'Take an infant CPR class before your baby arrives or in the first few months. Your hospital or pediatrician''s office usually offers them. It takes 2 hours and you hope to never use it.' WHERE slug = 'safety-infant-cpr';
UPDATE milestone_windows SET prep_tip = 'Get your car seat installed and inspected before your due date — many fire stations and hospitals offer free checks. You cannot leave the hospital without it.' WHERE slug = 'safety-car-seat-install-check';
UPDATE milestone_windows SET prep_tip = 'Crawling is coming — do the babyproofing now before you need it. Cover outlets, secure heavy furniture, add stair gates, and get cabinet locks. One weekend of setup prevents months of chasing.' WHERE slug = 'safety-babyproofing';
UPDATE milestone_windows SET prep_tip = 'Water safety is not age-limited — it requires constant touch supervision at every age near any water. Now is the time to build that habit before your baby becomes mobile.' WHERE slug = 'safety-water-supervision';
UPDATE milestone_windows SET prep_tip = 'The newborn hearing screen happens at the hospital within the first day or two. No prep needed — just know it''s coming and that a refer result means a follow-up, not a diagnosis.' WHERE slug = 'screening-newborn-hearing';
UPDATE milestone_windows SET prep_tip = 'The newborn metabolic screen is a heel prick done at the hospital before discharge. Nothing to prepare — just know it''s routine and covers 30+ conditions.' WHERE slug = 'screening-newborn-blood-spot';
UPDATE milestone_windows SET prep_tip = 'Jaundice is common in newborns and checked before hospital discharge. Know the signs: yellowing of skin and whites of eyes. If you see it at home after discharge, call your pediatrician.' WHERE slug = 'screening-newborn-bilirubin';
UPDATE milestone_windows SET prep_tip = 'Your first pediatrician visit happens at 3 to 5 days — it''s already booked if you chose your pediatrician before birth. If not, call today.' WHERE slug = 'screening-visit-3to5-days';
UPDATE milestone_windows SET prep_tip = 'Book your 2-month well-child visit now if you haven''t. Vaccines are given at this visit — expect a fussier evening afterward. Have infant acetaminophen on hand.' WHERE slug = 'screening-visit-2months';
UPDATE milestone_windows SET prep_tip = 'Book your 4-month well-child visit. The developmental check at this visit looks for head control, social smile, and tracking — all things you''ve been working on.' WHERE slug = 'screening-visit-4months';
UPDATE milestone_windows SET prep_tip = 'Book your 6-month well-child visit. This is a big one — developmental check, vaccines, and the start of the solid food conversation.' WHERE slug = 'screening-visit-6months';
UPDATE milestone_windows SET prep_tip = 'Book your 9-month well-child visit. This visit includes a developmental surveillance check and is the last one before the major 12-month milestone appointment.' WHERE slug = 'screening-visit-9months';
UPDATE milestone_windows SET prep_tip = 'Book your 12-month well-child visit — this is a major developmental checkpoint. The pediatrician will check for walking, words, and social development.' WHERE slug = 'screening-visit-12months';
UPDATE milestone_windows SET prep_tip = 'Book your 15-month well-child visit. Bring a word count — how many words is your child saying consistently? The pediatrician will ask.' WHERE slug = 'screening-visit-15months';
UPDATE milestone_windows SET prep_tip = 'Book your 18-month well-child visit now — this one includes the M-CHAT autism screen. Complete the questionnaire based on what your child actually does, not what you hope they do.' WHERE slug = 'screening-visit-18months-autism';
UPDATE milestone_windows SET prep_tip = 'Book your 24-month well-child visit — a second autism screen (M-CHAT-R/F) is given here. Bring your language observations: sentence length, clarity, vocabulary breadth.' WHERE slug = 'screening-visit-24months-autism';
UPDATE milestone_windows SET prep_tip = 'Book your 30-month well-child visit. Bring language observations — sentence length, clarity, and vocabulary breadth. This is the last screen before the 3-year visit.' WHERE slug = 'screening-visit-30months';
UPDATE milestone_windows SET prep_tip = 'Book your 36-month well-child visit — the final Scout milestone checkpoint. Prepare a summary of what your child can do: speech clarity, self-help skills, social interaction.' WHERE slug = 'screening-visit-36months';
UPDATE milestone_windows SET prep_tip = 'Book your baby''s first dental visit now if you haven''t. Most pediatric dentists want to see babies by their first tooth or first birthday. Don''t wait for a problem.' WHERE slug = 'screening-dental-first-visit';
UPDATE milestone_windows SET prep_tip = 'Breast milk doesn''t contain enough vitamin D. Get infant vitamin D drops before your baby arrives — 400 IU daily starting within the first few days of life.' WHERE slug = 'nutrition-vitamin-d-breastfed';
UPDATE milestone_windows SET prep_tip = 'Formula is fortified with vitamin D — no supplement needed if your baby is formula-fed. Confirm this at the first pediatrician visit.' WHERE slug = 'nutrition-vitamin-d-formula';
UPDATE milestone_windows SET prep_tip = 'If you plan to breastfeed, connect with a lactation consultant before birth if possible — it''s much easier to troubleshoot before than after. Your OB or midwife can refer you.' WHERE slug = 'nutrition-breastfeeding-establishment';
UPDATE milestone_windows SET prep_tip = 'Watch for the three readiness signs before starting solids: good head control, ability to sit with support, and losing the tongue-thrust reflex. Not a specific age.' WHERE slug = 'nutrition-solids-readiness';
UPDATE milestone_windows SET prep_tip = 'Get a few soft-tipped spoons and a suction bowl before starting solids. A blender or food processor for purees is useful but not essential — fork-mashed banana and avocado work fine.' WHERE slug = 'nutrition-first-purees';
UPDATE milestone_windows SET prep_tip = 'Iron-rich foods should be among the first solids you introduce. Think pureed meat, iron-fortified cereal, or pureed legumes — not just fruit and vegetables.' WHERE slug = 'nutrition-iron-fortified-foods';
UPDATE milestone_windows SET prep_tip = 'Mild white fish like cod or tilapia, flaked fine or pureed, is a good first fish. Rich in omega-3s. Introduce on a quiet day at home.' WHERE slug = 'nutrition-fish-intro';
UPDATE milestone_windows SET prep_tip = 'Wheat is easily introduced through iron-fortified cereals or soft bread pieces. One of the simpler allergens to work into regular meals.' WHERE slug = 'nutrition-wheat-intro';
UPDATE milestone_windows SET prep_tip = 'A small amount of tahini mixed into puree is the easiest sesame introduction. Introduce on its own before combining with other new foods.' WHERE slug = 'nutrition-sesame-intro';
UPDATE milestone_windows SET prep_tip = 'Plain full-fat yogurt or mild soft cheese are the easiest dairy introductions at this stage. Start with a small amount and watch for reaction.' WHERE slug = 'nutrition-dairy-intro';
UPDATE milestone_windows SET prep_tip = 'Pick up a simple weighted sippy cup or 360 cup. Introducing it now, before the 12-month bottle-weaning window, gives your baby time to practice without pressure.' WHERE slug = 'nutrition-sippy-cup';
UPDATE milestone_windows SET prep_tip = 'Move from smooth purees to mashed and lumpy textures — fork-mashed banana, soft-cooked vegetables. Texture progression now prevents pickiness later.' WHERE slug = 'nutrition-texture-mashed';
UPDATE milestone_windows SET prep_tip = 'Soft finger foods are coming — start thinking in pea-sized pieces of soft cooked vegetables, banana, or soft pasta. The pincer grasp and the eating skill develop together.' WHERE slug = 'nutrition-texture-finger-foods';
UPDATE milestone_windows SET prep_tip = 'Start moving toward three meals and two snacks daily. The rhythm of structured meal timing now makes toddler eating significantly easier later.' WHERE slug = 'nutrition-3-meals-rhythm';
UPDATE milestone_windows SET prep_tip = 'Start thinking about your meals as their meals — modified for texture. Removing salt and adding variety now means less pickiness later.' WHERE slug = 'nutrition-family-foods';
UPDATE milestone_windows SET prep_tip = 'Start transitioning away from the bottle now — the longer it continues past 12 months, the harder it becomes. Replace one feeding at a time with a cup.' WHERE slug = 'nutrition-bottle-weaning';
UPDATE milestone_windows SET prep_tip = 'Stock whole cow milk before the 12-month birthday so you''re ready to make the switch. Introduce it gradually mixed with formula or breast milk if your baby resists the taste.' WHERE slug = 'nutrition-cows-milk-switch';
UPDATE milestone_windows SET prep_tip = 'Honey can contain botulism spores and must not be given to babies under 12 months. Check food labels — some surprising products contain honey.' WHERE slug = 'nutrition-honey-avoidance';
UPDATE milestone_windows SET prep_tip = 'Whole milk is nutritious but displaces solid food if over-consumed. 16 to 24 ounces per day is the target — no more. Set that habit from the start.' WHERE slug = 'nutrition-milk-cap';
UPDATE milestone_windows SET prep_tip = 'Give your baby maximum floor time on a firm, safe surface. Rolling requires freedom to try — a bouncy seat doesn''t build the same strength.' WHERE slug = 'motor-roll-tummy-to-back';
UPDATE milestone_windows SET prep_tip = 'Once rolling tummy to back is established, back to tummy follows. Keep the floor clear and safe and let them explore the full range of movement.' WHERE slug = 'motor-roll-back-to-tummy';
UPDATE milestone_windows SET prep_tip = 'Start propping your baby to sit using a Boppy pillow or your own hands. Short supported-sit sessions build the core strength needed for independent sitting.' WHERE slug = 'motor-sitting-supported';
UPDATE milestone_windows SET prep_tip = 'Dangle a toy just within reach during tummy time or while lying on their back. The motivation to reach is what builds the skill.' WHERE slug = 'motor-reaching-grabbing';
UPDATE milestone_windows SET prep_tip = 'Place your baby on a firm surface with a boppy ring around them and step back. Independent sitting is almost here — give it space to develop.' WHERE slug = 'motor-sitting-unsupported';
UPDATE milestone_windows SET prep_tip = 'Baby-proof the floor now. Crawling can arrive quickly and the floor becomes their world. Get down on your hands and knees and check for hazards at that height.' WHERE slug = 'motor-crawling';
UPDATE milestone_windows SET prep_tip = 'Lower the crib mattress this week. Once pulling to stand begins, the crib rail height matters for safety. Also check that furniture being used to pull up is stable.' WHERE slug = 'motor-pull-to-stand';
UPDATE milestone_windows SET prep_tip = 'Create a cruising path of stable furniture pieces. This is the last phase before walking. Check that everything they''ll grab onto won''t tip over.' WHERE slug = 'motor-cruising';
UPDATE milestone_windows SET prep_tip = 'Small, soft finger foods are perfect for practicing the pincer grasp — pea-sized pieces of soft cooked vegetables, banana, or pasta. The eating is almost secondary to the fine motor work.' WHERE slug = 'motor-pincer-grasp';
UPDATE milestone_windows SET prep_tip = 'Clear open floor space — carpets, parks, any long flat surface. Running attempts start with falling. That''s normal and part of it.' WHERE slug = 'motor-running';
UPDATE milestone_windows SET prep_tip = 'Jumping with both feet takes real coordination. A low foam step or small trampoline gives a fun safe surface to practice. Demonstrate and invite copying.' WHERE slug = 'motor-jumping-both-feet';
UPDATE milestone_windows SET prep_tip = 'Get a set of unit blocks or stackable cups. Stacking requires both fine motor control and spatial reasoning — leave them accessible for open-ended play.' WHERE slug = 'motor-stacking-blocks-3';
UPDATE milestone_windows SET prep_tip = 'Get a set of unit blocks or stackable cups if you don''t have them. Stacking 6 requires fine motor control and patience. Let them problem-solve the wobble.' WHERE slug = 'motor-stacking-blocks-6';
UPDATE milestone_windows SET prep_tip = 'Offer small safe objects and watch your baby pass them hand to hand. Toys with easy gripping handles work well at this stage.' WHERE slug = 'motor-object-transfer';
UPDATE milestone_windows SET prep_tip = 'Talk to your baby constantly. Describe what you''re doing, name things, use a warm animated voice. You''re building their brain with every word.' WHERE slug = 'language-cooing';
UPDATE milestone_windows SET prep_tip = 'Your baby''s first laugh is close. Gentle tickles, funny faces, and silly sounds are the most reliable triggers. Be ready — it will make your whole week.' WHERE slug = 'language-laughing';
UPDATE milestone_windows SET prep_tip = 'Imitate your baby''s sounds back to them and watch them imitate you. This reciprocal sound play is building the scaffolding for first words.' WHERE slug = 'language-imitating-sounds';
UPDATE milestone_windows SET prep_tip = 'Start waving goodbye and hello consistently with the word — every time, with your baby watching. Imitation of social gestures develops from this repetitive modeling.' WHERE slug = 'language-waving';
UPDATE milestone_windows SET prep_tip = 'Say ''no'' clearly and consistently, with a calm voice and neutral face. Your baby is building the connection between the word and the limit — tone matters as much as the word.' WHERE slug = 'language-understands-no';
UPDATE milestone_windows SET prep_tip = 'Start giving clear one-step instructions without gesture: ''Get your shoes.'' ''Put that down.'' Your child is starting to understand these — give the language a chance to land.' WHERE slug = 'language-1step-commands';
UPDATE milestone_windows SET prep_tip = 'Bath time is the easiest venue for body part practice — everything is visible and accessible. Aim for 5 named parts by 18 months: head, nose, eyes, mouth, belly.' WHERE slug = 'language-body-parts-5';
UPDATE milestone_windows SET prep_tip = 'When reading aloud, point to pictures as you name them. Your baby is building the bridge between spoken words and their referents — pointing makes it visible.' WHERE slug = 'language-read-with-pointing';
UPDATE milestone_windows SET prep_tip = 'Start singing nursery rhymes from day one — your baby doesn''t care that you can''t carry a tune. The rhythm and repetition are building early language circuits.' WHERE slug = 'language-songs-rhymes';
UPDATE milestone_windows SET prep_tip = 'Start giving two-step instructions naturally: ''Get your shoes and bring them to me.'' Pause between steps to let your child process before acting.' WHERE slug = 'language-2step-commands';
UPDATE milestone_windows SET prep_tip = 'Model correct pronoun use without correcting mistakes. When they say ''me want it,'' you say ''you want it? Let me get it for you.'' Imitation is how they learn.' WHERE slug = 'language-pronouns';
UPDATE milestone_windows SET prep_tip = 'If strangers frequently can''t understand what your child is saying, note that for the next visit. Some clarity gap is normal; more than 50% unintelligible by 24 months is worth flagging.' WHERE slug = 'language-stranger-understands-50pct';
UPDATE milestone_windows SET prep_tip = 'If strangers frequently struggle to understand your child, note specific observations for the 30-month visit. Speech clarity should be improving steadily through this period.' WHERE slug = 'language-stranger-understands-75pct';
UPDATE milestone_windows SET prep_tip = 'Embed color naming in daily life rather than drilling: ''Pass me the yellow cup.'' ''Look at that red car.'' Repetition in context beats repetition in isolation.' WHERE slug = 'language-names-colors';
UPDATE milestone_windows SET prep_tip = 'Count everything together as you go about your day — stairs, crackers, toys. Three is the target but the habit of counting is what matters most.' WHERE slug = 'language-counts-to-3';
UPDATE milestone_windows SET prep_tip = 'After outings, ask open-ended questions: ''What happened at the park today?'' Give them time to organize their thoughts. Narrate back what you heard to model storytelling structure.' WHERE slug = 'language-tells-stories';
UPDATE milestone_windows SET prep_tip = 'Name emotions as they happen in everyday life: ''You seem frustrated.'' ''That made you happy.'' Building an emotional vocabulary now pays off in the tantrum years ahead.' WHERE slug = 'language-label-emotions';
UPDATE milestone_windows SET prep_tip = 'Practice one-to-one counting by touching each object: ''One bear, two bears, three bears — three!'' The touch and the final total number are the two key elements.' WHERE slug = 'language-counts-objects-5';
UPDATE milestone_windows SET prep_tip = 'Practice name and age in play: ''What''s your name? How old are you?'' Frame it as a game, not a quiz. By 30 months this should be automatic.' WHERE slug = 'language-knows-name-age';
UPDATE milestone_windows SET prep_tip = 'Start giving multi-step instructions in natural conversation: ''Go get your shoes, put them on, and come to the door.'' Your child''s comprehension is ahead of their speech.' WHERE slug = 'language-complex-instructions';
UPDATE milestone_windows SET prep_tip = 'If you find yourself frequently interpreting for others what your child said, note it. A significant clarity gap at this stage is worth raising with your pediatrician.' WHERE slug = 'language-speech-clarity-family';
UPDATE milestone_windows SET prep_tip = 'High-contrast black-and-white images capture newborn attention best. A few printed cards or a simple mobile near the changing table is all you need.' WHERE slug = 'cognitive-visual-stimulation';
UPDATE milestone_windows SET prep_tip = 'Move a brightly colored object slowly across your baby''s field of vision and watch their eyes follow. No equipment needed — just deliberate face and object time.' WHERE slug = 'cognitive-visual-tracking';
UPDATE milestone_windows SET prep_tip = 'No prep needed. Show up, make eye contact, and respond to your baby. Recognition develops from repetition of your face and voice.' WHERE slug = 'cognitive-recognizes-caregiver';
UPDATE milestone_windows SET prep_tip = 'Hide a toy under a cloth and watch your baby''s reaction. This is the test for emerging object permanence — the understanding that things still exist when out of sight.' WHERE slug = 'cognitive-object-permanence-emerging';
UPDATE milestone_windows SET prep_tip = 'Hide a toy completely under a blanket and watch your baby search for it. Full object permanence — searching for completely hidden objects — should be solid by 9 months.' WHERE slug = 'cognitive-object-permanence-solid';
UPDATE milestone_windows SET prep_tip = 'Do simple actions in front of your baby and watch them copy — clapping, banging a surface, waving. Imitation is how they learn everything.' WHERE slug = 'cognitive-imitation-play';
UPDATE milestone_windows SET prep_tip = 'Make sure there are a few simple pretend play props accessible: a toy phone, a baby doll, a toy cup. You don''t need to direct the play — just make the props available.' WHERE slug = 'cognitive-pretend-play-emerging';
UPDATE milestone_windows SET prep_tip = 'When reading aloud, pause and point to a picture: ''Where''s the dog?'' Your child is about to start pointing to pictures when you name them — encourage it.' WHERE slug = 'cognitive-points-to-pictures';
UPDATE milestone_windows SET prep_tip = 'Bath time is the best venue for body part naming — everything is visible and accessible. ''Where''s your nose? Ear? Knee?'' Rotate through 5 to 10 parts.' WHERE slug = 'cognitive-identifies-body-parts';
UPDATE milestone_windows SET prep_tip = 'Add props to the play space that support multi-step pretend scenarios — a toy kitchen, baby doll with accessories, simple dress-up items. The more open-ended, the better.' WHERE slug = 'cognitive-pretend-play-complex';
UPDATE milestone_windows SET prep_tip = 'Get a simple matching game or shape sorter if you don''t have one. Categorizing by attribute (all the red ones here) is a bigger cognitive step than it looks.' WHERE slug = 'cognitive-matches-shapes-colors';
UPDATE milestone_windows SET prep_tip = 'Keep up daily counting practice embedded in routine activities. Counting stairs, crackers, or toys is more effective than sitting down to count abstractly.' WHERE slug = 'cognitive-counts-to-10';
UPDATE milestone_windows SET prep_tip = 'Start pointing out same and different in everyday contexts: ''These socks match — they''re the same.'' ''This block is big, that one is different — it''s little.''' WHERE slug = 'cognitive-same-different';
UPDATE milestone_windows SET prep_tip = 'Leave simple problems for your child to solve rather than solving them immediately. A lid that''s almost off, a drawer that needs a pull — small problems build persistence.' WHERE slug = 'cognitive-simple-problem-solving';
UPDATE milestone_windows SET prep_tip = 'After outings, ask open-ended recall questions: ''What did we see at the park today?'' Give your child time to organize the memory. Don''t fill in the blanks too quickly.' WHERE slug = 'cognitive-memory-recalls-events';
UPDATE milestone_windows SET prep_tip = 'Place an unbreakable mirror at floor level during tummy time. Your baby will be fascinated by the face they see — self-recognition develops gradually from this practice.' WHERE slug = 'cognitive-self-recognition-mirror';
UPDATE milestone_windows SET prep_tip = 'Stranger anxiety is coming — completely normal and a sign of healthy attachment. Brief, calm, consistent separations help your baby learn: you leave, you come back.' WHERE slug = 'social-stranger-anxiety';
UPDATE milestone_windows SET prep_tip = 'Practice short separations with trusted adults now so the pattern is established before daycare or school drop-offs begin. Keep goodbyes brief and confident.' WHERE slug = 'social-separation-anxiety';
UPDATE milestone_windows SET prep_tip = 'Peek-a-boo is about to become your most useful trick. It teaches object permanence — you disappear, you come back — which is also the foundation for separation tolerance.' WHERE slug = 'social-peek-a-boo';
UPDATE milestone_windows SET prep_tip = 'Arrange low-key playdates with one same-age child. Expect them to play next to each other, not really together — that''s parallel play, and it''s exactly right for this stage.' WHERE slug = 'social-parallel-play';
UPDATE milestone_windows SET prep_tip = 'Model comforting behavior in front of your child: comfort a stuffed animal, name the emotion. When your child sees someone upset, narrate what''s happening.' WHERE slug = 'social-empathy-emerging';
UPDATE milestone_windows SET prep_tip = 'Name your child''s emotions as they happen — ''You''re frustrated'' or ''That scared you.'' Building emotional vocabulary now lays the groundwork for self-regulation later.' WHERE slug = 'social-label-big-feelings';
UPDATE milestone_windows SET prep_tip = 'Build extra time into routines now. The ''me do it'' phase is coming and the children who are allowed to try — even slowly — build more confidence and fewer meltdowns.' WHERE slug = 'social-independence-me-do-it';
UPDATE milestone_windows SET prep_tip = 'If your child is naming a favorite friend, take it seriously — arrange a playdate. Short, one-on-one, same-age play is the right format. Ninety minutes is plenty.' WHERE slug = 'social-peer-friendships';
UPDATE milestone_windows SET prep_tip = 'Skin-to-skin and diaper changes are for all caregivers, not just the birth parent. The bonding neurochemistry is the same. Start those routines from day one.' WHERE slug = 'social-father-partner-bonding';
UPDATE milestone_windows SET prep_tip = 'If starting daycare or a new caregiver, do gradual transitions — short visits first, then half days. The relationship needs time to build before full separation.' WHERE slug = 'social-caregiver-transition';
UPDATE milestone_windows SET prep_tip = 'When your baby makes a sound or expression, copy it back. That simple loop — they do something, you respond, they respond — is the foundation of language and social development.' WHERE slug = 'social-serve-return-loop';
UPDATE milestone_windows SET prep_tip = 'You cannot pour from an empty cup. Before your baby arrives, identify the one thing that most recharges you and build a plan to protect it — even if it''s just 20 minutes.' WHERE slug = 'social-parent-self-care';
UPDATE milestone_windows SET prep_tip = 'Start a consistent bedtime routine now — bath, feed, song, sleep. Predictability is a form of safety for your baby. The exact routine matters less than the consistency.' WHERE slug = 'social-bedtime-routine-security';
UPDATE milestone_windows SET prep_tip = 'Decide your discipline approach before you need it, not in the moment. Calm, consistent, brief responses to limit-testing are more effective than escalation.' WHERE slug = 'social-consistent-discipline';
UPDATE milestone_windows SET prep_tip = 'Lead screening is recommended between 6 and 12 months for high-risk populations. Ask your pediatrician if a blood lead test is appropriate at your next visit.' WHERE slug = 'screening-blood-lead';
UPDATE milestone_windows SET prep_tip = 'Vision screening begins at the 12-month well-child visit. If you''ve noticed any squinting, eye-crossing, or asymmetric gaze before then, mention it sooner.' WHERE slug = 'screening-vision-12months';
UPDATE milestone_windows SET prep_tip = 'Save your poison control number now: in the US it''s 1-800-222-1222. Add it to your phone before you need it, not while you''re panicking.' WHERE slug = 'safety-poison-control';
UPDATE milestone_windows SET prep_tip = 'Sunscreen can be used starting at 6 months. Get a mineral sunscreen (zinc oxide or titanium dioxide) and apply before any outdoor time.' WHERE slug = 'safety-sunscreen-6months';
UPDATE milestone_windows SET prep_tip = 'The crib-to-bed transition works best when it''s not rushed. If your child isn''t climbing out, there''s no urgency — most children do best in a crib until age 2.5 to 3.' WHERE slug = 'safety-crib-to-bed-transition';
UPDATE milestone_windows SET prep_tip = 'The car seat forward-facing transition is based on weight and height limits, not age. Check your seat''s manual — many children should still be rear-facing well past age 2.' WHERE slug = 'safety-forward-facing-transition';
UPDATE milestone_windows SET prep_tip = 'Formula is fortified with vitamin D — no supplement needed if your baby is formula-fed. Confirm this at the first pediatrician visit.' WHERE slug = 'nutrition-vitamin-d-formula';
UPDATE milestone_windows SET prep_tip = 'Tofu cubes or edamame, mashed, are easy soy introductions. Soft, easy to portion, and straightforward to add to puree.' WHERE slug = 'nutrition-soy-intro';
UPDATE milestone_windows SET prep_tip = 'A small amount of water in a sippy cup alongside solid meals is recommended starting at 6 months. 2 to 4 ounces per day is plenty at this stage.' WHERE slug = 'nutrition-water-cup';
UPDATE milestone_windows SET prep_tip = 'Let them use the spoon themselves even though it''s slower and messier. You can guide hand-over-hand for the scoop and then step back for the delivery.' WHERE slug = 'nutrition-spoon-self-feeding';
UPDATE milestone_windows SET prep_tip = 'Add a toddler fork to meals alongside the spoon. Soft foods — banana chunks, cooked pasta, soft vegetables — work best for early forking attempts.' WHERE slug = 'nutrition-fork-intro';
UPDATE milestone_windows SET prep_tip = 'At age 2, the AAP recommends switching from whole milk to 2% or low-fat. Plan the transition for right around the 24-month birthday.' WHERE slug = 'nutrition-2pct-milk-switch';
UPDATE milestone_windows SET prep_tip = 'Start building structured snack routines — same times, whole foods, no grazing. Toddler eating habits are easier to establish now than to reform at age 3.' WHERE slug = 'nutrition-healthy-snack-patterns';
UPDATE milestone_windows SET prep_tip = 'Limit juice and sugary foods from the start — dental decay can begin as soon as the first tooth appears. Water and breast milk or formula are the only drinks needed before 12 months.' WHERE slug = 'nutrition-dental-diet';
UPDATE milestone_windows SET prep_tip = 'Offer small safe objects and watch your baby pass them hand to hand. Toys with easy gripping handles work well at this stage.' WHERE slug = 'motor-object-transfer';
UPDATE milestone_windows SET prep_tip = 'Check your stair gate latches now. Stair climbing with support is about to begin and unsupervised stair access is not safe at this stage.' WHERE slug = 'motor-stair-climbing';
UPDATE milestone_windows SET prep_tip = 'Pick up a large soft ball if you don''t have one. That''s the only preparation. Place it on the floor and step back.' WHERE slug = 'motor-kicking-ball';
UPDATE milestone_windows SET prep_tip = 'Get a box of thick crayons and a roll of cheap paper. Tape it to a low surface. Scribbling is about to become a daily activity.' WHERE slug = 'motor-scribbling';
UPDATE milestone_windows SET prep_tip = 'Draw a vertical line slowly in front of your child and invite them to try. Use chunky crayons and large paper. The attempt matters, not the result.' WHERE slug = 'motor-drawing-line';
UPDATE milestone_windows SET prep_tip = 'Draw a circle slowly in front of your child and invite them to try. Circles are harder than lines — expect a wobbly oval for many months before a recognizable circle emerges.' WHERE slug = 'motor-drawing-circle';
UPDATE milestone_windows SET prep_tip = 'Jumping forward from a standing position requires balance and timing. Mark a start line and a landing spot — toddlers love a target to aim for.' WHERE slug = 'motor-jumping-forward';
UPDATE milestone_windows SET prep_tip = 'Hopping on one foot requires core strength and balance. Practice the one-foot balance first before expecting a full hop — ''stand like a flamingo'' is a good starting game.' WHERE slug = 'motor-hopping-one-foot';
UPDATE milestone_windows SET prep_tip = 'Roll a large ball toward your child and work up to a gentle underhand toss. Catching requires tracking the ball and timing the grab — it develops gradually over many months.' WHERE slug = 'motor-catching-ball';
UPDATE milestone_windows SET prep_tip = 'Keep singing with your baby. Songs with repeated phrases and built-in pauses — ''The Wheels on the Bus,'' ''Old MacDonald'' — are especially effective for language learning.' WHERE slug = 'language-singing-together';
UPDATE milestone_windows SET prep_tip = 'When ''why?'' starts, take it seriously. Answer honestly at an age-appropriate level. The child who learns that questions get real answers becomes a lifelong learner.' WHERE slug = 'language-asks-why';
UPDATE milestone_windows SET prep_tip = 'Give your baby toys that do something when touched — buttons that light up, rattles, crinkle toys. Cause-and-effect exploration is how they learn they can affect the world.' WHERE slug = 'cognitive-cause-effect';
UPDATE milestone_windows SET prep_tip = 'Set out containers of different sizes during floor play. Putting things in and taking them out is about to become a sustained activity — it''s building fine motor and spatial reasoning.' WHERE slug = 'cognitive-container-play';
UPDATE milestone_windows SET prep_tip = 'A simple shape sorter — circle, square, triangle — is the ideal prep toy for this window. Buy one now and leave it accessible. No instruction needed; they''ll figure it out.' WHERE slug = 'cognitive-shape-sorter';
UPDATE milestone_windows SET prep_tip = 'Start using ''mine'' and ''yours'' clearly in daily language. Understanding possession is foundational for navigating social situations — and for eventually learning to share.' WHERE slug = 'cognitive-mine-yours';
UPDATE milestone_windows SET prep_tip = 'Give your child access to objects with obvious functions — a toy phone, a toy broom, a toy cup. Watch them use them correctly. That''s symbolic thinking in action.' WHERE slug = 'cognitive-function-of-objects';
UPDATE milestone_windows SET prep_tip = 'Start using time words consistently: ''We''ll go to the park this afternoon.'' ''Grandma is coming tomorrow.'' Concepts like morning, afternoon, and tomorrow develop from language use.' WHERE slug = 'cognitive-time-concepts';
UPDATE milestone_windows SET prep_tip = 'Name animals and their sounds during books, toys, and outdoor time. ''Dog — what does the dog say? Woof!'' The pairing of word, image, and sound builds vocabulary fast.' WHERE slug = 'cognitive-animals-sounds';
UPDATE milestone_windows SET prep_tip = 'Use ''more'' and ''all done'' with consistent hand gestures at every meal. Your baby will use these signs back to you before they can say the words.' WHERE slug = 'cognitive-more-all-done';
UPDATE milestone_windows SET prep_tip = 'Use size words constantly in daily narration: ''big spoon, little spoon,'' ''that''s a big dog, this is a little dog.'' Relative size concepts develop from consistent language exposure.' WHERE slug = 'cognitive-big-little';
UPDATE milestone_windows SET prep_tip = 'Forced sharing doesn''t teach sharing — it teaches resentment. Practice turn-taking instead: ''Liam''s turn, then your turn.'' True sharing emerges naturally around age 3.' WHERE slug = 'social-sharing-not-before-3';
UPDATE milestone_windows SET prep_tip = 'Before your baby arrives, set up the sleep space: firm flat mattress, no loose bedding, nothing in the crib. This takes 10 minutes to get right and zero minutes to fix later.' WHERE slug = 'prebirth-safe-sleep-setup';
UPDATE milestone_windows SET prep_tip = 'Start packing your hospital bag now — most parents wish they''d done it earlier. Focus on comfort items for labor and the first 24 hours, not the whole stay.' WHERE slug = 'prebirth-hospital-bag';
UPDATE milestone_windows SET prep_tip = 'Now is the time to choose a pediatrician, not after the baby is born. Most pediatric practices require a prenatal consult appointment — book it in the next few weeks.' WHERE slug = 'prebirth-pediatrician-selection';
UPDATE milestone_windows SET prep_tip = 'Newborn hearing and metabolic screens happen at the hospital automatically — nothing to prepare. Just know they''re coming so you''re not surprised when a nurse wheels in a machine.' WHERE slug = 'prebirth-newborn-screening';
UPDATE milestone_windows SET prep_tip = 'Pick up a small weighted open cup. Introduce it at one meal a day with just a small amount of water. Spills are expected and fine.' WHERE slug = 'self-help-open-cup';
UPDATE milestone_windows SET prep_tip = 'You don''t need to do anything special — just resist the urge to stop the switch-flipping and drawer-opening that''s about to start. It''s intentional learning.' WHERE slug = 'cognitive-cause-effect-exploration';
UPDATE milestone_windows SET prep_tip = 'Show your child the feet-first, backward method for descending stairs. Demonstrate it slowly and repeat it every time. Keep stair gates in place during this learning phase.' WHERE slug = 'motor-stairs-descending';
UPDATE milestone_windows SET prep_tip = 'Shift your approach to dressing: narrate each step and let your child push their arm through or pull the shirt down. It takes longer but builds real independence.' WHERE slug = 'self-help-self-dressing-assist';
UPDATE milestone_windows SET prep_tip = 'Start watching for readiness signs: staying dry for 2 hours, signaling need, showing interest in the toilet. Don''t start training yet — just observe and note what you see.' WHERE slug = 'self-help-potty-readiness';
UPDATE milestone_windows SET prep_tip = 'Stock up on patience for ''What''s that?'' — it''s coming constantly. Answer every question genuinely. You are their dictionary and the habit of asking is exactly what you want.' WHERE slug = 'language-question-asking';
UPDATE milestone_windows SET prep_tip = 'Soft balls, open space, and your enthusiastic reaction — that''s all this milestone needs. A foam ball about the size of a tennis ball is ideal.' WHERE slug = 'motor-throw-overarm';
UPDATE milestone_windows SET prep_tip = 'Get chunky crayons and unlined paper on the regular rotation. Show your child a vertical line slowly and invite them to try. Keep the expectation low, the praise high.' WHERE slug = 'cognitive-draw-copy-lines';
UPDATE milestone_windows SET prep_tip = 'Be ready to laugh at deliberately wrong answers. Toddler humor is about expectation violation and your reaction is the entire reward.' WHERE slug = 'cognitive-humor-jokes';
UPDATE milestone_windows SET prep_tip = 'If you don''t have a balance bike or tricycle, now is the time to get one. Start with a balance bike if choosing — it builds the skill set that transfers to pedaling later.' WHERE slug = 'motor-tricycle-balance-bike';
UPDATE milestone_windows SET prep_tip = 'Start letting your child undress at bath time and bedtime without help. Velcro shoes and elastic waists are the right gear for this learning phase.' WHERE slug = 'self-help-undressing-independently';
UPDATE milestone_windows SET prep_tip = 'Get a second toothbrush so your child has their own to hold while you brush with yours. Choice of toothpaste flavor helps reduce resistance before it starts.' WHERE slug = 'self-help-tooth-brushing';
UPDATE milestone_windows SET prep_tip = 'Observe which hand your child reaches with consistently. If it''s the left hand, start sourcing left-handed scissors for when preschool begins. Tell caregivers not to redirect.' WHERE slug = 'motor-handedness-emerging';
UPDATE milestone_windows SET prep_tip = 'If your child mentions a friend''s name, take it seriously — arrange a playdate. Short, one-on-one, same-age play is the right format. Ninety minutes is plenty.' WHERE slug = 'social-named-friendships';
UPDATE milestone_windows SET prep_tip = 'Turn balance practice into a game: flamingo pose, stepping stones, counting how long they can hold it. Two seconds by 36 months is the milestone target.' WHERE slug = 'motor-balance-one-foot';
UPDATE milestone_windows SET prep_tip = 'Visit the preschool together before the first day — familiarity dramatically reduces first-day distress. Let your child explore the space at their own pace.' WHERE slug = 'cognitive-preschool-readiness';
UPDATE milestone_windows SET prep_tip = 'Lay out tomorrow''s clothes the night before and let your child get dressed independently in the morning. Remove time pressure and the process becomes much smoother.' WHERE slug = 'self-help-dressing-simple-clothes';
UPDATE milestone_windows SET prep_tip = 'Embed counting into daily life with emphasis on the total: ''One, two, three crackers — you have three!'' The final number as the quantity is the concept they''re building.' WHERE slug = 'cognitive-number-quantity';
UPDATE milestone_windows SET prep_tip = 'Model comforting behavior in front of your child: comfort a stuffed animal, name the emotion. When your child sees someone upset, narrate what''s happening and watch their response.' WHERE slug = 'social-comforting-behavior';
UPDATE milestone_windows SET prep_tip = 'If training is in progress, stay consistent with the potty routine: on waking, before meals, before leaving the house, before nap, and before bed. Consistency drives dryness.' WHERE slug = 'self-help-daytime-dryness';
UPDATE milestone_windows SET prep_tip = 'If you''re breastfeeding and want to introduce a bottle, 4 to 6 weeks is the recommended window — early enough that breastfeeding is established, late enough to avoid nipple confusion. Get a slow-flow bottle and have someone other than the primary nursing parent offer it.' WHERE slug = 'nutrition-bottle-intro-breastfed';
UPDATE milestone_windows SET prep_tip = 'Respond to every babble as if it''s a word. Copy the sounds back and wait for a response. This reciprocal sound play is building the conversational structure that words will eventually fill.' WHERE slug = 'language-babbling';
UPDATE milestone_windows SET prep_tip = 'Use your baby''s name frequently in natural interaction. The milestone is turning reliably toward their name — watch for that response across different rooms and situations.' WHERE slug = 'language-responds-to-name';
UPDATE milestone_windows SET prep_tip = 'Responsive caregiving — picking up, responding to cries, making eye contact — is literally building your baby''s brain right now. There''s no such thing as spoiling a baby under 6 months.' WHERE slug = 'social-primary-attachment';
UPDATE milestone_windows SET prep_tip = 'Keep arranging regular playdates with consistent peers. Cooperative play develops from the familiarity built over many interactions with the same children — one-off playdates help less.' WHERE slug = 'social-cooperative-play';
UPDATE milestone_windows SET prep_tip = 'Small, soft finger foods are perfect for practicing the pincer grasp — pea-sized pieces of soft cooked vegetables, banana, or soft pasta. The eating is almost secondary to the fine motor work.' WHERE slug = 'nutrition-self-feeding-pincer';
UPDATE milestone_windows SET prep_tip = 'Test your child''s understanding informally with natural prompts: ''Where is the dog?'' ''Can you bring me the cup?'' You''ll be surprised how many words they know that they can''t yet say.' WHERE slug = 'language-receptive-vocabulary';